<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>Kanban Board</title>
  <style>
    body { font-family: sans-serif; }

    #board {
      display: flex;
      width: 80%;
      margin: 20px auto;
    }

    #col-todo, #col-doing, #col-done {
      flex: 1;
      border: 1px solid #ccc;
      padding: 10px;
      min-height: 300px;
      overflow-y: auto;
    }

    .count {
      font-weight: bold;
      margin-bottom: 5px;
    }

    .card {
      background-color: #f9f9f9;
      border: 1px solid #ddd;
      padding: 10px;
      margin-bottom: 5px;
      cursor: grab;
      user-select: none;
    }

    .card-del {
      background-color: red;
      color: white;
      border: none;
      padding: 5px;
      cursor: pointer;
      margin-left: 5px;
    }

    #new-card, #add-card {
      padding: 5px;
      font-size: 16px;
    }
  </style>
</head>
<body>

  <h1>Kanban Board</h1>

  <input type="text" id="new-card" placeholder="New card title">
  <button id="add-card">Add Card</button>

  <div id="board">
    <div id="col-todo" class="column" draggable="true">
      <span class="count">0</span>
      <div id="todo-cards"></div>
    </div>
    <div id="col-doing" class="column" draggable="true">
      <span class="count">0</span>
      <div id="doing-cards"></div>
    </div>
    <div id="col-done" class="column" draggable="true">
      <span class="count">0</span>
      <div id="done-cards"></div>
    </div>
  </div>

  <script>
    const newCardInput = document.getElementById('new-card');
    const addCardButton = document.getElementById('add-card');
    const boardDiv = document.getElementById('board');
    const todoCol = document.getElementById('col-todo');
    const doingCol = document.getElementById('col-doing');
    const doneCol = document.getElementById('col-done');

    let cardIdCounter = 0;
    const localStorageKey = 'kanbanBoardState';

    function loadBoard() {
      const savedState = localStorage.getItem(localStorageKey);
      if (savedState) {
        const state = JSON.parse(savedState);
        renderCards(state.todo, '#todo-cards');
        renderCards(state.doing, '#doing-cards');
        renderCards(state.done, '#done-cards');
        updateCounts();
      }
    }

    function saveBoard() {
      const todoCards = Array.from(document.querySelectorAll('#todo-cards .card')).map(c => ({ id: ++cardIdCounter, column: 'todo' }));
      const doingCards = Array.from(document.querySelectorAll('#doing-cards .card')).map(c => ({ id: ++cardIdCounter, column: 'doing' }));
      const doneCards = Array.from(document.querySelectorAll('#done-cards .card')).map(c => ({ id: ++cardIdCounter, column: 'done' }));

      const boardState = { todo: todoCards, doing: doingCards, done: doneCards };
      localStorage.setItem(localStorageKey, JSON.stringify(boardState));
    }


    function renderCards(cards, cardContainer) {
      cardContainer.innerHTML = '';
      cards.forEach(card => {
        const cardElement = document.createElement('div');
        cardElement.classList.add('card');
        cardElement.id = `card-${card.id}`;
        cardElement.draggable = true;

        const titleText = card.column === 'todo' ? 'To Do' : card.column === 'doing' ? 'Doing' : 'Done';
        cardElement.textContent = `${titleText}: ${card.id} - ${card.text}`; // Added id to show card id, can be removed

        const deleteButton = document.createElement('button');
        deleteButton.classList.add('card-del');
        deleteButton.textContent = 'Delete';
        cardElement.appendChild(deleteButton);

        cardContainer.appendChild(cardElement);

        deleteButton.addEventListener('click', () => {
          removeCard(card.id);
        });
      });
    }


    function removeCard(cardId) {
      const cards = Array.from(document.querySelectorAll('.card'));
      const cardToRemove = document.getElementById(`card-${cardId}`);
      if (cardToRemove) {
        cards.forEach((card, index) => {
          if (card.id === cardId) {
            cardContainer = card.closest('.column');  // Find the column container
            cardContainer.removeChild(card);

            const savedState = localStorage.getItem(localStorageKey);
            if (savedState) {
              const state = JSON.parse(savedState);
              state[card.textContent.split(': ')[0]].splice(state[card.textContent.split(': ')[0]].findIndex(c => c.id === parseInt(cardId)), 1); // Correct way to update state in localStorage

                localStorage.setItem(localStorageKey, JSON.stringify(state));
            }
          }
        });
      }
    }



    function moveCard(card, targetColumn) {
      card.classList.remove('todo', 'doing', 'done');
      card.textContent = `${targetColumn} ${card.textContent.split(': ')[0]}`;

       //Update localStorage state
       const savedState = localStorage.getItem(localStorageKey);
       if (savedState) {
         const state = JSON.parse(savedState);
         let index = -1;
         for(let i=0; i < state[card.textContent.split(': ')[0]].length; ++i){
           if(state[card.textContent.split(': ')[0]][i].id === parseInt(card.id)){
             index = i;
             break;
           }
         }

         if (index !== -1) {
            state[card.textContent.split(': ')[0]][index].column = targetColumn;
            localStorage.setItem(localStorageKey, JSON.stringify(state));
          }


       }

    }

    addCardButton.addEventListener('click', () => {
      const text = newCardInput.value;
      if (text) {
        const cardElement = document.createElement('div');
        cardElement.classList.add('card');
        cardElement.id = `card-${cardIdCounter++}`;
        cardElement.draggable = true;

        const titleText = text === 'To Do' ? 'To Do' : text === 'Doing' ? 'Doing' : 'Done';
        cardElement.textContent = `${titleText}: ${cardIdCounter} - ${text}`;  //Added id to show card id, can be removed

        const deleteButton = document.createElement('button');
        deleteButton.classList.add('card-del');
        deleteButton.textContent = 'Delete';
        cardElement.appendChild(deleteButton);

        let columnToMove = 'todo';  // Default to 'todo' if no explicit column is provided
        if (newCardInput.value === "Doing") {columnToMove = "doing";}
        else if (newCardInput.value === "Done"){columnToMove = "done";}

        cardElement.addEventListener('dragstart', (e) => {
          e.dataTransfer.setData("text/plain", cardElement.id);
        });

        todoCol.addEventListener('dragover', (e) => {
            e.preventDefault();
        });

        todoCol.addEventListener('drop', (e) => {
          moveCard(cardElement, 'todo');
          updateCounts();
        });


        doingCol.addEventListener('dragover', (e) => {
            e.preventDefault();
        });
         doingCol.addEventListener('drop', (e) => {
          moveCard(cardElement, 'doing');
          updateCounts();
        });

        doneCol.addEventListener('dragover', (e) => {
            e.preventDefault();
        });
        doneCol.addEventListener('drop', (e) => {
          moveCard(cardElement, 'done');
          updateCounts();
        });



        newCardInput.value = '';
        renderCards(null, '#todo-cards'); // Refresh to add the new card
      }
    });

    function updateCounts() {
      document.querySelectorAll('.count').forEach(span => {
        span.textContent = Array.from(document.querySelectorAll('.card')).filter(c => c.closest('.column').id === 'col-todo').length;
      });
    }

    loadBoard();
  </script>

</body>
</html>
